function validate([head]) {
  if (!Array.isArray(head)) return 'head is a list of values and nulls.';
  if (head.length === 0) return null;
  if (head[0] === null) return 'The first row must start with a value.';
  if (head[head.length - 1] === null) return 'Leave out trailing nulls.';
  let count = 0;
  let previous = 0;
  let i = 0;
  while (i < head.length) {
    if (previous > 0) {
      // Skip the null that closes the row above, then count the nulls that position this row.
      i++;
      let offset = 0;
      while (head[i] === null) {
        offset++;
        i++;
      }
      if (offset >= previous) return 'Each row must hang from a node of the row above it.';
    }
    let length = 0;
    while (i < head.length && head[i] !== null) {
      const value = head[i];
      if (!Number.isInteger(value) || value < 1 || value > 100000) return 'Node values are whole numbers from 1 to 10^5.';
      length++;
      i++;
    }
    count += length;
    previous = length;
  }
  if (count > 1000) return 'The list has at most 1000 nodes.';
  return null;
}

