function adapt(input, solve, kit) {
  const [values] = input;
  class Node {
    constructor(val) { this.val = val; this.prev = null; this.next = null; this.child = null; }
  }
  // Rebuild the rows; each row after the first becomes the child list of one node in the row above.
  const nodes = [];
  let row = [];
  let i = 0;
  while (i < values.length) {
    let offset = 0;
    if (row.length > 0) {
      i++;
      while (values[i] === null) {
        offset++;
        i++;
      }
    }
    const above = row;
    row = [];
    while (i < values.length && values[i] !== null) {
      const node = new Node(values[i]);
      if (row.length > 0) {
        row[row.length - 1].next = node;
        node.prev = row[row.length - 1];
      }
      row.push(node);
      nodes.push(node);
      i++;
    }
    if (above.length > 0) above[offset].child = row[0];
  }
  const head = nodes.length > 0 ? nodes[0] : null;
  const result = solve(head);
  if (result === undefined) throw new Error('The solution did not return a value.');
  if (result !== head) throw new Error('Return the first node of the top level, which heads the flattened list.');
  // Walk the answer, checking that it reuses every node once with correct prev links and no children.
  const known = new Set(nodes);
  const seen = new Set();
  const out = [];
  let before = null;
  for (let node = result; node != null; node = node.next) {
    if (!known.has(node)) throw new Error('The flattened list must reuse the original nodes.');
    if (seen.has(node)) throw new Error('The next pointers form a loop.');
    seen.add(node);
    if ((node.prev ?? null) !== before) throw new Error(`The prev pointer of the node after ${before === null ? 'nothing (the head)' : before.val} is wrong.`);
    if (node.child != null) throw new Error(`A node with value ${node.val} still has a child.`);
    out.push(node.val);
    before = node;
  }
  if (out.length !== nodes.length) throw new Error('Some nodes are missing from the flattened list.');
  return out;
}

