function flatten(head) {
  let node = head;
  while (node !== null) {
    if (node.child !== null) {
      const child = node.child;
      let tail = child;
      while (tail.next !== null) {
        tail = tail.next;
      }
      tail.next = node.next;
      if (node.next !== null) {
        node.next.prev = tail;
      }
      node.next = child;
      child.prev = node;
      node.child = null;
    }
    node = node.next;
  }
  return head;
}

