function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const total = size === 'large' ? 900 + pick(101) : pick(12);
  if (total === 0) return [[]];
  // Rows are long, short (deep and thin) or mixed; values are wide or tiny so duplicates appear.
  const longest = size === 'large' ? 40 : [2, 4, 9][pick(3)];
  const tiny = size === 'small' && rand() < 0.5;
  const value = () => tiny ? 1 + pick(4) : 1 + pick(100000);
  const out = [];
  let left = total;
  let previous = 0;
  while (left > 0) {
    const length = Math.min(left, 1 + pick(longest));
    if (previous > 0) {
      out.push(null);
      const offset = pick(Math.min(previous, 20));
      for (let k = 0; k < offset; k++) out.push(null);
    }
    for (let k = 0; k < length; k++) out.push(value());
    left -= length;
    previous = length;
  }
  return [out];
}
